package fr.thegostsniperfr.arffornia.client.screen.title;

import fr.thegostsniperfr.arffornia.Arffornia;
import java.util.List;
import java.util.Locale;
import net.minecraft.resources.ResourceLocation;

/**
 * The title screen's TTF fonts, each declared at size 12 in {@code assets/arffornia/font/<family>/o<tier>.json}
 * once per oversample tier (generated by {@code tools/fonts/title_fonts.py}). Minecraft samples glyph textures
 * without filtering, so text is only sharp when its glyphs are rasterised near the size they cover on screen:
 * the screen picks the tier closest to the text's size in physical pixels.
 */
final class TitleFonts {
    static final float EM = 12f;
    static final List<Float> TIERS = List.of(0.5f, 0.625f, 0.8f, 1f, 1.25f, 1.6f, 2f, 2.5f, 3.2f, 4f, 5f, 6.4f, 8f, 10f, 12.5f, 16f, 20f);
    static final List<String> FAMILIES = List.of("display", "ui", "label", "body", "strong");

    private TitleFonts() {}

    /** The tier whose raster is closest (in ratio) to {@code pixelsPerEm} physical pixels per em. */
    static float tier(float pixelsPerEm) {
        float wanted = pixelsPerEm / EM, best = TIERS.getFirst();
        for (float t : TIERS) {
            if (Math.abs(Math.log(t / wanted)) < Math.abs(Math.log(best / wanted))) best = t;
        }
        return best;
    }

    static ResourceLocation font(String family, float pixelsPerEm) {
        return ResourceLocation.fromNamespaceAndPath(Arffornia.MODID, family + "/" + tierName(tier(pixelsPerEm)));
    }

    static String tierName(float tier) {
        String s = String.format(Locale.ROOT, "%s", tier);
        if (s.endsWith(".0")) s = s.substring(0, s.length() - 2);
        return "o" + s.replace('.', '_');
    }
}
